                  </div>
                  <div style={{ paddingBottom: last ? 0 : 18, minWidth: 0 }}>
                    <button ref={(el) => { tabRefs.current[i] = el; }} role="tab" aria-selected={on} tabIndex={on ? 0 : -1} onClick={() => go(i)}
