  const fillIn = (i, x, y, instant) => {
    const el = fillRefs.current[i];
    const w = wordRefs.current[i];
    if (!el || !w) return;
    const W = w.offsetWidth; const H = w.offsetHeight;
    const R = Math.hypot(Math.max(x, W - x), Math.max(y, H - y)) + 4;
