    el.style.clipPath = shape(R, x, y, W, H);
  };
  const fillOut = (i, x, y) => {
    const el = fillRefs.current[i];
    const w = wordRefs.current[i];
    if (!el || !w) return;
    el.style.transition = reduced ? 'none' : `clip-path ${Math.round(revealMs * 0.6)}ms cubic-bezier(0.3,0,0.2,1)`;
