              <rect x="1" y="8" width="5" height="5" fill="none" stroke="currentColor" strokeWidth="1.1" />
            </svg>
            <span className={`${p}-lbl`}>{shuffleLabel}</span>
          </button>
        </div>
      </div>
    </section>
  );
}

