              <span key={'r' + ran.n} style={{ display: 'block', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', color: text, animation: `${uid}-up 380ms ${easeOut} both` }}><span style={{ color: accent }}>●</span> Ran “{ran.label}”</span>
