  const hw = W / 2; const hh = H / 2;
  let coverIdx = -1;
  if (chain) {
    for (let j = N - 2; j >= 0; j--) {
      const f = metrics[j].focal;
      const z = chain.S[j] * Z;
      const dx = (chain.C[j].x + chain.S[j] * (f.x - metrics[j].cx) - cam.x) * Z;
      const dy = (chain.C[j].y + chain.S[j] * (f.y - metrics[j].cy) - cam.y) * Z;
