                <div key={j} style={{ width: compact ? 20 : 28, height: 2, background: muted, opacity: 0.35, position: 'relative' }}>
                  <div style={{ position: 'absolute', inset: 0, background: j === active ? accent : ink, transformOrigin: 'left', transform: `scaleX(${t})` }} />
                </div>
