        <div style={{ display: 'flex', flexDirection: compact ? 'column' : 'row', alignItems: compact ? 'flex-start' : 'center', gap: compact ? 18 : 32, minHeight: compact ? 0 : 64 }}>
          {phase !== 'thanks' ? (
