    const stagger = (o.stagger || 34) * speed;
    const dur = (o.dur || 360) * speed;
    const wave = o.wave ?? 0.4;
    const n = Math.max(fromS.length, toS.length);
    const chars = [];
    for (let i = 0; i < n; i++) {
      const s = now + i * stagger * wave;
