    }
  };

  const p = uid;
  const label = { fontFamily: mono, fontSize: compact ? 10 : 11, letterSpacing: '0.16em', textTransform: 'uppercase', color: muted };
  const navW = compact ? '100%' : `${(width - pad * 2) * 0.36}px`;

